package com.projectdark.mobile;
import android.content.*;import android.graphics.*;import java.util.*;import java.io.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class FramePerformanceV214Test {
 Context c;
 @Before public void setup(){c=RuntimeEnvironment.getApplication();for(String n:new String[]{"project_dark_f5m_v1","project_dark_journal_v1","project_dark_skill_test_v1"})c.getSharedPreferences(n,0).edit().clear().commit();F5mSaveStore.install(c);}
 void same(QuestJournalModel m,F5mAdaptedPrologueQuest q,GrowthQuest2 g,RpgProgressionState r){List<QuestJournalModel.Row> full=m.rows(q,g,false,r);QuestJournalModel.HudProjection hud=m.hud(q,g,false,r);assertEquals(m.attention(full),hud.attention);List<QuestJournalModel.Row> expected=MobileHudQuest.shown(full);assertEquals(expected.size(),hud.rows.size());for(int i=0;i<expected.size();i++){QuestJournalModel.Row a=expected.get(i),b=hud.rows.get(i);assertEquals(a.id,b.id);assertEquals(a.title,b.title);assertEquals(a.objective,b.objective);assertEquals(a.status,b.status);assertEquals(a.count,b.count);assertEquals(a.goal,b.goal);}}
 @Test public void compactHudMatchesJournalAcrossJobsAndLiveMutations()throws Exception{GameView v=new GameView(c);QuestJournalModel m=TownInteriorTest.field(v,"questJournalModel");F5mAdaptedPrologueQuest q=TownInteriorTest.field(v,"f5mQuest");GrowthQuest2 g=TownInteriorTest.field(v,"quest2");RuntimeState s=TownInteriorTest.field(v,"state");RpgProgressionState r=s.rpg();same(m,q,g,r);q.restore(F5mAdaptedPrologueQuest.State.COMPLETED,1);g.restore(GrowthQuest2.State.COMPLETED,3);for(String job:CampaignProgress.JOBS){assertTrue(r.restoreJobCode(job));for(int level:new int[]{3,41,99}){r.restoreProgression(level,0);r.campaign().syncOpening(true,true);same(m,q,g,r);CampaignProgress.Def d=r.campaign().next(r);if(d!=null)r.campaign().accept(d.id,r,null);same(m,q,g,r);}}}
 @Test public void profileFullJournalVersusHudAndRealFrames()throws Exception{GameView v=new GameView(c);v.layout(0,0,1536,864);RuntimeState s=TownInteriorTest.field(v,"state");s.rpg().restoreJobCode("WARRIOR");s.rpg().restoreProgression(99,250000000);QuestJournalModel m=TownInteriorTest.field(v,"questJournalModel");F5mAdaptedPrologueQuest q=TownInteriorTest.field(v,"f5mQuest");GrowthQuest2 g=TownInteriorTest.field(v,"quest2");long[] full=new long[60],hud=new long[60],draw=new long[120];for(int i=0;i<70;i++){long t=System.nanoTime();m.rows(q,g,false,s.rpg());long a=System.nanoTime();m.hud(q,g,false,s.rpg());long b=System.nanoTime();if(i>=10){full[i-10]=a-t;hud[i-10]=b-a;}}Bitmap b=Bitmap.createBitmap(1536,864,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);for(int i=0;i<draw.length+10;i++){long t=System.nanoTime();v.draw(canvas);if(i>=10)draw[i-10]=System.nanoTime()-t;}JSONObject out=new JSONObject().put("environment","host native CPU; not phone FPS").put("inventory",s.rpg().inventory().size()).put("fullJournal",stats(full)).put("compactHud",stats(hud)).put("wholeFrame",stats(draw));File f=new File("build/reports/horror-v179/v214/performance.json");f.getParentFile().mkdirs();try(FileWriter w=new FileWriter(f)){w.write(out.toString(2));}try(FileOutputStream w=new FileOutputStream(new File(f.getParent(),"milles-hud.png"))){b.compress(Bitmap.CompressFormat.PNG,100,w);}b.recycle();System.out.println(out);}
 JSONObject stats(long[] x)throws Exception{Arrays.sort(x);return new JSONObject().put("p50ms",x[x.length/2]/1e6).put("p95ms",x[(int)(x.length*.95)]/1e6).put("p99ms",x[(int)(x.length*.99)]/1e6).put("maxms",x[x.length-1]/1e6);}
}
